# Collect changed files
# ---------------------------------------------------------------------------

if [[ -n "${GITHUB_BASE_REF:-}" ]]; then
  # Running inside GitHub Actions pull_request event
  CHANGED_FILES=$(git diff --name-only "origin/${GITHUB_BASE_REF}" HEAD 2>/dev/null || git diff --name-only HEAD~1 HEAD)
