  # Running locally — inspect staged files, fall back to last commit
  CHANGED_FILES=$(git diff --cached --name-only 2>/dev/null)
  if [[ -z "$CHANGED_FILES" ]]; then
    CHANGED_FILES=$(git diff --name-only HEAD~1 HEAD 2>/dev/null || true)
