IMPACT_HIGH=false
IMPACT_MEDIUM=false

while IFS= read -r file; do
  # High impact: project files, CI, security configs, infrastructure
  if [[ "$file" == *.csproj || "$file" == package.json || "$file" == Cargo.toml || \
        "$file" == go.mod || "$file" == pyproject.toml || "$file" == build.gradle || \
        "$file" == .github/workflows/*.yml || "$file" == .github/workflows/*.yaml || \
